import{_ as e,o as a,c as s,ag as o}from"./chunks/framework.DXGyWiRo.js";const g=JSON.parse('{"title":"导出到 ApiPost","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/export-apipost.md","filePath":"zh/guide/export-apipost.md","lastUpdated":1789862141000}'),i={name:"zh/guide/export-apipost.md"};function d(r,t,p,n,l,h){return a(),s("div",null,[...t[0]||(t[0]=[o(`<h1 id="导出到-apipost" tabindex="-1">导出到 ApiPost <a class="header-anchor" href="#导出到-apipost" aria-label="Permalink to &quot;导出到 ApiPost&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">Beta 功能</p><p>ApiPost 通道默认关闭，使用前请先在 <strong>Features</strong> 标签页中启用。</p></div><p>EasyYapi 可以将 HTTP 接口导出到 <a href="https://www.apipost.cn/" target="_blank" rel="noreferrer">ApiPost</a> 项目。配置了 token 和项目时，接口通过 ApiPost 开放接口直接推送；未配置时，会写出 <code>apipost.json</code> 导入文件，供手动导入。</p><h2 id="启用通道" tabindex="-1">启用通道 <a class="header-anchor" href="#启用通道" aria-label="Permalink to &quot;启用通道&quot;">​</a></h2><p>打开 <kbd>Settings</kbd> &gt; <kbd>Other Settings</kbd> &gt; <kbd>EasyApi</kbd> &gt; <kbd>Features</kbd>，在 <strong>Export Channels</strong> 下启用 <strong>ApiPost (Beta)</strong>，然后重新打开 Settings 才能看到 ApiPost 标签页——与其它 beta 通道一样，需要先启用再配置。</p><h2 id="配置目标项目" tabindex="-1">配置目标项目 <a class="header-anchor" href="#配置目标项目" aria-label="Permalink to &quot;配置目标项目&quot;">​</a></h2><p>打开 <kbd>Settings</kbd> &gt; <kbd>Other Settings</kbd> &gt; <kbd>EasyApi</kbd> &gt; <kbd>ApiPost (Beta)</kbd>：</p><table tabindex="0"><thead><tr><th>字段</th><th>作用域</th><th>说明</th></tr></thead><tbody><tr><td><strong>Server</strong></td><td>Application</td><td>ApiPost 的地址，默认 <code>https://open.apipost.net</code>。仅用于拼接 <code>/open/apis/*</code> 请求 URL，绝不会写进你的文档。</td></tr><tr><td><strong>Token</strong></td><td>Application</td><td>ApiPost 开放接口 token，以 <code>api-token</code> 请求头发送。</td></tr><tr><td><strong>Team</strong></td><td>—</td><td>点击 <strong>Load</strong> 拉取该 token 可访问的团队，然后选择一个。</td></tr><tr><td><strong>Project</strong></td><td>Project</td><td>点击 <strong>Refresh</strong> 列出所选团队的项目，选择目标项目。</td></tr></tbody></table><p>token 和 server 在整个 IDE 中只保存一份；项目 id 按仓库保存，因此切换仓库时会切换到对应的目标项目，而不会静默复用上一个仓库的配置。</p><p>项目只能选择、不能手填：项目 id 是一串不可读的字符串，手填出错时不会有任何提示。已配置但不在拉取结果中的 id 仍会作为独立选项保留，因此指向当前团队以外项目的仓库依然可用。</p><h2 id="导出" tabindex="-1">导出 <a class="header-anchor" href="#导出" aria-label="Permalink to &quot;导出&quot;">​</a></h2><ol><li>打开包含接口的文件，或在 Project 视图中选择文件/文件夹。</li><li>选择 <strong>EasyYapi</strong> &gt; <strong>Export</strong> &gt; <strong>ApiPost (Beta)</strong>，或使用 API Explorer 中的 ApiPost 动作。</li><li>可在导出对话框中选择目标项目；不选择则使用已配置的项目。</li></ol><p>该通道仅支持 HTTP。gRPC 接口会被跳过，因为 ApiPost 无法表示它们。如果所选范围内没有 HTTP 接口，导出会提示没有可导出的内容。</p><h3 id="推送-vs-文件" tabindex="-1">推送 vs. 文件 <a class="header-anchor" href="#推送-vs-文件" aria-label="Permalink to &quot;推送 vs. 文件&quot;">​</a></h3><table tabindex="0"><thead><tr><th>情况</th><th>结果</th></tr></thead><tbody><tr><td>已配置 token <strong>和</strong> 项目 id</td><td>项目被就地更新，结果会报告新建/更新的接口数量。</td></tr><tr><td>两者缺一</td><td>写出 <code>apipost.json</code> 文件。在 ApiPost 中选择 <strong>导入</strong> → 「ApiPost 格式」→ 上传该文件即可。</td></tr></tbody></table><h2 id="两个-url-刻意彼此独立" tabindex="-1">两个 URL，刻意彼此独立 <a class="header-anchor" href="#两个-url-刻意彼此独立" aria-label="Permalink to &quot;两个 URL，刻意彼此独立&quot;">​</a></h2><p>ApiPost 导出会解析两个互不相关的 URL，二者互不推导：</p><table tabindex="0"><thead><tr><th>规则</th><th>含义</th></tr></thead><tbody><tr><td><code>apipost.host</code></td><td>ApiPost 自身的地址，仅用于拼装开放接口请求。默认取 Server 字段的值。</td></tr><tr><td><code>apipost.server.url</code></td><td>你正在编写的 API 的基础地址，会写入导入文档的前置 URL，使导入后的接口指向你自己的服务。</td></tr></tbody></table><p>把两者混用会让所有导入的接口都指向 ApiPost 自身。<code>apipost.server.url</code> 未设置时留空。</p><h2 id="apipost-规则" tabindex="-1">ApiPost 规则 <a class="header-anchor" href="#apipost-规则" aria-label="Permalink to &quot;ApiPost 规则&quot;">​</a></h2><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 本次导出的目标项目</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">apipost.project</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=1234567890abcdef</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 写入导入文档的基础地址</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">apipost.server.url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=https://api.example.com</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 开放接口地址覆盖（通常不需要）</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">apipost.host</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=https://open.apipost.net</span></span></code></pre></div><table tabindex="0"><thead><tr><th>规则</th><th>说明</th></tr></thead><tbody><tr><td><code>apipost.project</code></td><td>目标项目 id，覆盖已配置的项目</td></tr><tr><td><code>apipost.host</code></td><td>ApiPost 开放接口地址覆盖</td></tr><tr><td><code>apipost.server.url</code></td><td>被导出 API 的基础地址，写入文档的 host/base_path</td></tr><tr><td><code>apipost.export.before</code></td><td>导出开始前触发一次的事件</td></tr><tr><td><code>apipost.save.before</code></td><td>推送单个接口前触发，<code>document</code> 绑定可被修改</td></tr><tr><td><code>apipost.save.after</code></td><td>推送单个接口后触发，暴露 <code>content</code> 与 <code>result</code></td></tr></tbody></table><p>规则语法见 <a href="/settings/config-rule">配置规则</a>。</p><h2 id="重复导出行为" tabindex="-1">重复导出行为 <a class="header-anchor" href="#重复导出行为" aria-label="Permalink to &quot;重复导出行为&quot;">​</a></h2><p>重复导出同一批接口是更新（upsert）而非重复创建。接口按 <strong>请求方法 + 路径</strong> 与项目中已有节点匹配；ApiPost 开放接口没有批量导入路由，因此推送按依赖顺序进行：</p><ol><li><strong>文件夹</strong> —— 已存在时按名称复用，因为父节点缺失时子节点会被拒绝创建。</li><li><strong>数据模型</strong> —— 按名称去重，并在引用它们的接口之前推送。</li><li><strong>接口</strong> —— 就地创建或更新。</li></ol><p>服务端重新生成的文件夹和模型 id 会在子节点推送前回填到 <code>parent_id</code> 与 <code>$ref</code> 中，因为只有服务端返回的 id 才是可信来源。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/guide/export-openapi">导出到 OpenAPI</a> —— 输出可移植的契约文件，而非推送项目</li><li><a href="/guide/export2yapi">导出到 YApi</a> —— 推送接口到 YApi 项目</li><li><a href="/settings/ide-setting">IDE 设置</a> —— ApiPost 设置标签页说明</li></ul>`,29)])])}const b=e(i,[["render",d]]);export{g as __pageData,b as default};
